css:
@media (max-width: 767px) {
  .chips { position: relative; flex-wrap: nowrap; overflow-x: auto; padding-bottom: 8px; }
  .chip, .chips .link-btn { flex: none; white-space: nowrap; }
  .chips::-webkit-scrollbar { height: 6px; }
  .chips::-webkit-scrollbar-track { background: #eef0f3; border-radius: 3px; }
  .chips::-webkit-scrollbar-thumb { background: #b7bec8; border-radius: 3px; }
}
